INSERT INTO paa.Updates_Cumulative (
    Id,
    Title,
    Description,
    Date,
    Severity,
    Priority
)
VALUES (
    @Id,
    @Title,
    @Description,
    CAST(@Date AS DATE),
    @Severity,
    @Priority
);

SELECT @Id AS CumulativeId;

